/**
 * Spec
 *
 * The specification, split along the questions agents actually ask.
 *
 * v1 had one `description` blob plus a `prompts.starter` that largely restated it.
 */
export type Spec = {
    /**
     * Constraints
     *
     * Hard requirements and prohibitions (markdown).
     */
    constraints?: string | null;
    /**
     * Context
     *
     * Read-this-first pointers with reasons.
     */
    context?: Array<ContextPointer>;
    /**
     * Description
     *
     * WHAT to do (markdown) -- the working spec.
     */
    description: string;
    /**
     * Intent
     *
     * WHY this task exists (markdown).
     */
    intent?: string | null;
    /**
     * Out Of Scope
     *
     * Explicit non-goals, so agents do not wander.
     */
    out_of_scope?: string | null;
    /**
     * Summary
     *
     * One or two sentences. The only summary, for every audience.
     */
    summary: string;
};

/**
 * Task
 *
 * A task, in schema v2.
 *
 * The five consistency rules from design doc section 3 are enforced below in
 * ``_check_consistency``. They are what make limbo unrepresentable: an open task with
 * nobody responsible, or a handoff with no stated ask, cannot be written down.
 */
export type Task = {
    /**
     * Acceptance
     */
    acceptance?: Array<AcceptanceCriterion>;
    /**
     * Archived
     *
     * Visibility flag, orthogonal to how the task ended.
     */
    archived?: boolean;
    assignment?: Assignment;
    /**
     * Who acts next. Required while open.
     */
    ball?: Ball | null;
    /**
     * Ball Prompt
     *
     * The ask, addressed to whoever holds the ball. Required when ball is set.
     */
    ball_prompt?: string | null;
    /**
     * Why they hold it, scoped to the holder.
     */
    ball_reason?: BallReason | null;
    /**
     * Branches
     */
    branches?: Array<Branch>;
    /**
     * Category
     *
     * Project taxonomy; validated against config.
     */
    category: string;
    /**
     * Created
     */
    created: string;
    /**
     * Deliverables
     */
    deliverables?: Array<Deliverable>;
    /**
     * Dependencies
     */
    dependencies?: Array<Dependency>;
    /**
     * Display Status
     *
     * One human-readable label, derived on read and never stored.
     *
     * Storing it was rejected in design doc section 3: a denormalized copy of three
     * fields is a drift bug waiting for its moment, and the derivation is this.
     * A computed field rather than a plain property so API responses carry it;
     * storage excludes it on write, and a file that contains it is rejected by
     * name (extra="forbid") rather than silently round-tripped.
     */
    readonly display_status: string;
    /**
     * Effort
     *
     * Free text. An estimate, not a contract.
     */
    effort?: string | null;
    /**
     * Id
     *
     * Unique task identifier.
     */
    id: string;
    lifecycle?: Lifecycle;
    /**
     * Links
     */
    links?: Array<Link>;
    /**
     * Log
     */
    log?: Array<LogEntry>;
    /**
     * How it ended. Set only when closed.
     */
    outcome?: Outcome | null;
    /**
     * Parent
     *
     * Task id of the umbrella task, if any.
     */
    parent?: string | null;
    priority?: Priority;
    /**
     * Schema
     *
     * Schema version stamp. Always 2 for this model (D3).
     */
    schema?: number;
    spec: Spec;
    /**
     * Tags
     */
    tags?: Array<string>;
    /**
     * Title
     *
     * Task title.
     */
    title: string;
    /**
     * Updated
     */
    updated: string;
};

/**
 * TaskCreateRequest
 *
 * Payload for creating a new task.
 */
export type TaskCreateRequest = {
    /**
     * Acceptance
     *
     * Checklist defining done.
     */
    acceptance?: Array<AcceptanceCriterion>;
    /**
     * Actor
     *
     * Configured actor id to record as the creator. Written to the creation log entry, so a task can say who filed it. Refused when the project does not define the id.
     */
    actor?: string | null;
    /**
     * Attachments
     *
     * Images evidencing the report, stored as sidecar files.
     */
    attachments?: Array<AttachmentUpload>;
    /**
     * Branches
     *
     * Git branches associated with the task lifecycle.
     */
    branches?: Array<Branch>;
    /**
     * Category
     *
     * Classification category used for filtering in the UI.
     */
    category?: string;
    /**
     * Constraints
     *
     * Hard requirements and prohibitions (spec.constraints).
     */
    constraints?: string | null;
    /**
     * Context
     *
     * Curated read-this-first paths and why each one matters (spec.context).
     */
    context?: Array<ContextPointer>;
    /**
     * Deliverables
     *
     * Deliverables to be produced for task completion.
     */
    deliverables?: Array<Deliverable>;
    /**
     * Dependencies
     *
     * Task dependencies tracked in the system.
     */
    dependencies?: Array<Dependency>;
    /**
     * Description
     *
     * Markdown working spec (spec.description).
     */
    description: string;
    /**
     * Effort
     *
     * Estimated effort (time or complexity). Free text.
     */
    effort?: string | null;
    /**
     * Eligible
     *
     * Actor ids that may claim the task. Empty means anyone.
     */
    eligible?: Array<string>;
    /**
     * Id
     *
     * Optional explicit task identifier (e.g., task-042).
     */
    id?: string | null;
    /**
     * Intent
     *
     * Why the task exists (spec.intent).
     */
    intent?: string | null;
    /**
     * Initial lifecycle: draft (ball human/spec) or ready (agent/available).
     */
    lifecycle?: Lifecycle;
    /**
     * Links
     *
     * External references relevant to the task.
     */
    links?: Array<Link>;
    /**
     * Operation Id
     *
     * Caller-generated UUID. Resending the same request with the same id replays the original result instead of writing again; reusing it for a different request is a conflict and writes nothing.
     */
    operation_id?: string | null;
    /**
     * Out Of Scope
     *
     * Explicit non-goals (spec.out_of_scope).
     */
    out_of_scope?: string | null;
    /**
     * Parent
     *
     * Umbrella task id, if any.
     */
    parent?: string | null;
    /**
     * Relative urgency for the new task.
     */
    priority?: Priority;
    /**
     * Summary
     *
     * One-or-two sentence spec.summary. Defaults to the title.
     */
    summary?: string | null;
    /**
     * Tags
     *
     * Arbitrary tag labels.
     */
    tags?: Array<string>;
    /**
     * Title
     *
     * Task title summarising the work to be done.
     */
    title: string;
};

