/**
 * VersionResponse
 *
 * What a client needs to decide whether it can talk to this service.
 *
 * Two independent numbers. ``version`` is the installed AgentJobs distribution and
 * governs the shape of the REST surface; ``schema_version`` is the task-record
 * schema and governs the shape of the documents that surface returns. A client can
 * match one and not the other, so neither is derivable from the other.
 */
export type VersionResponse = {
    /**
     * Schema Version
     *
     * Task record schema version served.
     */
    schema_version: number;
    /**
     * Source Root
     *
     * Directory this process imported its own code from. Startup refuses when that is the wrong checkout, but the answer is reported here too: on a machine with several worktrees it is the difference between a stale server and a wrongly-installed one, and guessing costs a forensic session.
     */
    source_root: string;
    /**
     * Version
     *
     * Installed AgentJobs package version.
     */
    version: string;
    /**
     * Yaml Loader
     *
     * Which YAML parser reads task files. The pure-Python fallback is about thirteen times slower than libyaml and is the usual explanation for a sluggish install, so it is reported rather than left to be guessed at.
     */
    yaml_loader: string;
};

